  haloTxt(arrows.text('O₂ flux — slow').font({ family: FONT, size: 11, anchor: 'middle' }).fill('#9a3030').center(0, 104));

  var haloL = g.group(), molL = g.group();
  var nodes = MOLS.map(function (m) {
    var h = haloL.circle(m.r * 3.4).center(0, 0).fill(m.kind === 'H2' ? '#7fc4e8' : '#8e1212').opacity(0);
    var c = molL.circle(m.r * 2).center(0, 0)
      .fill(m.kind === 'H2' ? '#ffffff' : RED)
      .stroke(m.kind === 'H2' ? { color: '#c3d4d4', width: 1.2 } : { color: '#a8181d', width: 0.8 });
