// @FIGURE_CODE_BEGIN
var figW = 640, figH = 470;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, figW, figH).attr('preserveAspectRatio', 'xMidYMid meet');

var SAGE = '#9fc3c3', PALE = '#dcecec', RED = '#cc2127', TEXTC = '#333333';
var FONT = 'Helvetica, Arial, sans-serif';

var bulbGrad = draw.gradient('radial', function (add) {
  add.stop(0, '#f6fcfc'); add.stop(0.55, '#e2f1f0'); add.stop(1, '#d2e6e6');
});
bulbGrad.attr({ cx: 0.36, cy: 0.30, r: 0.80 });

function haloTxt(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
  return t;
}

/* ───────── molecule data (local apparatus coordinates) ───────── */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    var t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
var rng = mulberry32(20240617);
var placed = { '-1': [], '1': [] };
function place(side, r, minD) {
  var cxb = side * 150, best = null, list = placed[side];
  for (var k = 0; k < 45; k++) {
    var a = rng() * Math.PI * 2, rad = Math.sqrt(rng()) * (95 - r - 9);
    var p = { x: cxb + Math.cos(a) * rad, y: Math.sin(a) * rad };
    var ok = true;
    for (var i = 0; i < list.length; i++) {
      var dx = list[i].x - p.x, dy = list[i].y - p.y;
      if (dx * dx + dy * dy < minD * minD) { ok = false; break; }
    }
    if (ok) { list.push(p); return p; }
    best = p;
  }
  list.push(best); return best;
}

var MOLS = [];
function addSpecies(kind, count, side, nCross, s0, s1, dur, r) {
  var homes = [], i;
  for (i = 0; i < count; i++) homes.push(place(side, r, 14));
  for (i = 0; i < count; i++) {
    var m = {
      kind: kind, r: r, side: side, home: homes[i], crosses: i < nCross, dur: dur,
      amp: (kind === 'H2' ? 3.4 : 1.9),
      f1: (kind === 'H2' ? 2.1 : 1.05) * (0.75 + rng() * 0.5),
      f2: (kind === 'H2' ? 1.7 : 0.85) * (0.75 + rng() * 0.5),
      ph1: rng() * 6.283, ph2: rng() * 6.283
    };
    if (m.crosses) m.s = s0 + (s1 - s0) * ((i + 0.5) / nCross) + (rng() - 0.5) * 4;
    MOLS.push(m);
  }
}
addSpecies('H2', 24, -1, 12, 6, 66, 10, 6.5);
addSpecies('O2', 28, 1, 14, 18, 80, 14, 7.5);
MOLS.forEach(function (m) { if (m.crosses) m.dest = place(-m.side, m.r, 14); });

function lerp(a, b, u) { return { x: a.x + (b.x - a.x) * u, y: a.y + (b.y - a.y) * u }; }

function molPos(m, t, wob) {
  var u = 0;
  if (m.crosses && t > m.s) u = Math.min(1, (t - m.s) / m.dur);
  var p;
  if (u <= 0) p = { x: m.home.x, y: m.home.y };
  else if (u >= 1) p = { x: m.dest.x, y: m.dest.y };
  else {
    var e = u * u * (3 - 2 * u);
    var A = m.home, B = { x: m.side * 58, y: 0 }, C = { x: -m.side * 58, y: 0 }, D = m.dest;
    if (e < 0.42) p = lerp(A, B, e / 0.42);
    else if (e < 0.58) p = lerp(B, C, (e - 0.42) / 0.16);
    else p = lerp(C, D, (e - 0.58) / 0.42);
  }
  var narrow = Math.abs(p.x) < 78 ? 0.22 : 1;
  var x = p.x + m.amp * narrow * Math.sin(m.f1 * wob + m.ph1);
  var y = p.y + m.amp * narrow * Math.cos(m.f2 * wob + m.ph2);
  if (Math.abs(x) <= 58) {
    if (y > 7) y = 7; if (y < -7) y = -7;
  } else {
    var cb = x < 0 ? -150 : 150, dx = x - cb, dy = y, d = Math.sqrt(dx * dx + dy * dy);
    var mx = 95 - m.r - 3;
    if (d > mx) { x = cb + dx / d * mx; y = dy / d * mx; }
  }
  return { x: x, y: y };
}

/* ───────── apparatus renderer ───────── */
function fluxArrow(parent, x1, x2, y, w, color) {
  var gg = parent.group();
  var dir = x2 > x1 ? 1 : -1;
  gg.line(x1, y, x2 - dir * 10, y).stroke({ color: color, width: w, linecap: 'round' });
  gg.polygon([[x2, y], [x2 - dir * 12, y - 5.5], [x2 - dir * 12, y + 5.5]]).fill(color);
  return gg;
}

function makeApparatus(cx, cy, scale, interactive) {
  var g = draw.group().attr('transform', 'translate(' + cx + ',' + cy + ') scale(' + scale + ')');

  var bl = g.circle(190).center(-150, 0).fill(bulbGrad).stroke({ color: SAGE, width: 4 });
  var br = g.circle(190).center(150, 0).fill(bulbGrad).stroke({ color: SAGE, width: 4 });
  g.rect(124, 26).move(-62, -13).fill('#dcecec').stroke('none');
  g.line(-62, -13, 62, -13).stroke({ color: SAGE, width: 4, linecap: 'round' });
  g.line(-62, 13, 62, 13).stroke({ color: SAGE, width: 4, linecap: 'round' });

  var valve = g.group();
  valve.rect(16, 14).move(-8, 20).fill(PALE).stroke({ color: SAGE, width: 3 });
  valve.rect(26, 11).move(-13, 32).fill(PALE).stroke({ color: SAGE, width: 3 });
  valve.rect(30, 46).move(-15, -23).radius(7).fill(PALE).stroke({ color: SAGE, width: 3.5 });
  valve.rect(12, 16).move(-6, -35).fill(PALE).stroke({ color: SAGE, width: 3 });

  var closedG = valve.group();
  closedG.ellipse(15, 24).center(0, -46).fill(PALE).stroke({ color: SAGE, width: 3 });
  closedG.circle(11).center(0, -58).fill(PALE).stroke({ color: SAGE, width: 3 });
  closedG.ellipse(17, 24).center(0, 0).fill('#cfe3e3').stroke({ color: SAGE, width: 3 });

  var openG = valve.group();
  openG.ellipse(48, 13).center(0, -40).fill(PALE).stroke({ color: SAGE, width: 3 });
  openG.ellipse(16, 7).center(0, -49).fill(PALE).stroke({ color: SAGE, width: 2.5 });

  var arrows = g.group().opacity(0);
  fluxArrow(arrows, -66, 66, 60, 4.6, '#3f88c5');
  haloTxt(arrows.text('H₂ flux — fast').font({ family: FONT, size: 15, anchor: 'middle' }).fill('#2f6fa5').center(0, 43));
  fluxArrow(arrows, 42, -42, 88, 2.4, '#b03a3a');
  haloTxt(arrows.text('O₂ flux — slow').font({ family: FONT, size: 13, anchor: 'middle' }).fill('#9a3030').center(0, 105));

  var haloL = g.group(), molL = g.group();
  var nodes = MOLS.map(function (m) {
    var h = haloL.circle(m.r * 3.4).center(0, 0).fill(m.kind === 'H2' ? '#7fc4e8' : '#8e1212').opacity(0);
    var c = molL.circle(m.r * 2).center(0, 0)
      .fill(m.kind === 'H2' ? '#ffffff' : RED)
      .stroke(m.kind === 'H2' ? { color: '#c3d4d4', width: 1.2 } : { color: '#a8181d', width: 0.8 });
    if (interactive) {
      c.css('cursor', 'pointer');
      c.on('mousemove', function (e) {
        showTooltip(m.kind === 'H2'
          ? 'H₂ — 2 g/mol: light, highest average speed, crosses first'
          : 'O₂ — 32 g/mol: 16× heavier, ~4× slower average speed', e);
      }).on('mouseleave', hideTooltip).on('click', function () {
        showPopup(m.kind === 'H2' ? 'A hydrogen molecule' : 'An oxygen molecule',
          m.kind === 'H2'
            ? 'H₂ has a molar mass of 2 g/mol. At the same temperature every gas has the same average kinetic energy, so the tiny H₂ molecules must move about four times faster than O₂ (√(32/2) = 4). Nothing pushes them — they simply wander until they are spread evenly.'
            : 'O₂ has a molar mass of 32 g/mol. Same temperature, same average kinetic energy, but 16× the mass means about one-quarter the average speed, so oxygen seeps into the hydrogen bulb far more slowly than hydrogen invades the oxygen bulb.');
      });
    }
    return { m: m, c: c, h: h };
  });

  if (interactive) {
    [[bl, 'Left bulb (started as pure H₂)'], [br, 'Right bulb (started as pure O₂)']].forEach(function (pair) {
      pair[0].css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip(pair[1] + ' — see the counter beneath it', e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup(pair[1], 'Each bulb starts with a single pure gas. Once the stopcock opens, random molecular motion carries molecules down their own concentration gradient until both gases occupy both bulbs; the motion never stops, but the net flux falls to zero when the concentrations are equal.');
        });
    });
    valve.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Stopcock — the only barrier between the two gases', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The stopcock', 'Closed, the plug blocks the bore and the two gases stay perfectly separated. Opened, the bore is clear and molecules pass through in both directions purely by chance — diffusion needs no pump, fan, or pressure difference.');
      });
  }

  function update(t, mass, wob) {
    var lH = 0, lO = 0, rH = 0, rO = 0;
    for (var i = 0; i < nodes.length; i++) {
      var n = nodes[i], p = molPos(n.m, t, wob);
      n.c.center(p.x, p.y);
      n.h.center(p.x, p.y).opacity(mass ? 0.30 : 0);
      if (p.x < 0) { if (n.m.kind === 'H2') lH++; else lO++; }
      else { if (n.m.kind === 'H2') rH++; else rO++; }
    }
    var open = t > 0;
    closedG.opacity(open ? 0 : 1);
    openG.opacity(open ? 1 : 0);
    arrows.opacity(mass && open && t < 96 ? 1 : 0);
    return { lH: lH, lO: lO, rH: rH, rO: rO };
  }
  return { g: g, update: update };
}

/* ───────── legend (top row, readable) ───────── */
var leg = draw.group();
leg.circle(11).center(150, 22).fill('#ffffff').stroke({ color: '#c3d4d4', width: 1.2 });
leg.text('H₂ — 2 g/mol (light, fast)').font({ family: FONT, size: 13 }).fill('#55676b').move(161, 14);
leg.circle(13).center(370, 22).fill(RED).stroke({ color: '#a8181d', width: 0.8 });
leg.text('O₂ — 32 g/mol (heavy, slow)').font({ family: FONT, size: 13 }).fill('#55676b').move(381, 14);

/* ───────── main apparatus + labels ───────── */
var MAIN_S = 0.95, MAIN_CX = 320, MAIN_CY = 168;
var main = makeApparatus(MAIN_CX, MAIN_CY, MAIN_S, true);
var bulbLx = MAIN_CX - 150 * MAIN_S, bulbRx = MAIN_CX + 150 * MAIN_S;

haloTxt(draw.text('H₂').font({ family: FONT, size: 21, anchor: 'middle' }).fill(TEXTC).center(bulbLx, 58));
haloTxt(draw.text('O₂').font({ family: FONT, size: 21, anchor: 'middle' }).fill(TEXTC).center(bulbRx, 58));

var countL = draw.text('').font({ family: FONT, size: 13, anchor: 'middle' }).fill('#5b6b6b').center(bulbLx, 285);
var countR = draw.text('').font({ family: FONT, size: 13, anchor: 'middle' }).fill('#5b6b6b').center(bulbRx, 285);
var caption = draw.text('Stopcock closed').font({ family: FONT, size: 17.5, anchor: 'middle' }).fill(TEXTC).center(MAIN_CX, 312);

/* ───────── three-panel reference strip (legible) ───────── */
draw.line(20, 332, 620, 332).stroke({ color: '#e4ebeb', width: 1 });
var stripX = [107, 320, 533], stripT = [0, 28, 100], stripHi = [], stripCard = [];
stripX.forEach(function (x, i) {
  var card = draw.rect(196, 126).move(x - 98, 336).radius(8)
    .fill('#ffffff').stroke({ color: '#e4ebeb', width: 1 });
  stripCard.push(card);
  var hi = draw.rect(196, 126).move(x - 98, 336).radius(8).fill('#eaf6f6').opacity(0);
  stripHi.push(hi);

  var ap = makeApparatus(x, 373, 0.33, false);
  ap.update(stripT[i], false, 0);

  if (i === 2) {
    draw.text('Some time after').font({ family: FONT, size: 13, anchor: 'middle' }).fill('#4d5a5a').center(x, 414);
    draw.text('Stopcock open').font({ family: FONT, size: 13, anchor: 'middle' }).fill('#4d5a5a').center(x, 430);
  } else {
    draw.text(['Stopcock closed', 'Stopcock open'][i]).font({ family: FONT, size: 13, anchor: 'middle' }).fill('#4d5a5a').center(x, 430);
  }
  draw.text('(' + 'abc'[i] + ')').font({ family: FONT, size: 13, anchor: 'middle' }).fill('#4d5a5a').center(x, 450);

  var hit = draw.rect(196, 126).move(x - 98, 336).fill('#000').opacity(0).css('cursor', 'pointer');
  hit.on('mousemove', function (e) {
    showTooltip('Textbook panel (' + 'abc'[i] + ') — click to set the apparatus above to this stage', e);
  }).on('mouseleave', hideTooltip)
    .on('click', function () { playing = false; setPlayLabel(); setTime(stripT[i]); });
});

/* ───────── state / render loop ───────── */
var state = { t: 0, mass: false };
var wob = 0, lastTs = 0, playing = false;

function render() {
  var c = main.update(state.t, state.mass, wob);
  countL.text('H₂ ' + c.lH + '  ·  O₂ ' + c.lO).center(bulbLx, 285);
  countR.text('H₂ ' + c.rH + '  ·  O₂ ' + c.rO).center(bulbRx, 285);
  var cap = state.t === 0 ? 'Stopcock closed' : (state.t < 60 ? 'Stopcock open' : 'Some time after Stopcock open');
  caption.text(cap).center(MAIN_CX, 312);
  var act = state.t === 0 ? 0 : (state.t < 60 ? 1 : 2);
  for (var i = 0; i < stripHi.length; i++) {
    stripHi[i].opacity(i === act ? 1 : 0);
    stripCard[i].stroke({ color: i === act ? '#9fc3c3' : '#e4ebeb', width: i === act ? 1.6 : 1 });
  }
}

function setTime(v) {
  state.t = Math.max(0, Math.min(100, v));
  var inp = document.getElementById('elapsedTimeInput');
  var out = document.getElementById('elapsedTimeVal');
  if (inp) inp.value = Math.round(state.t);
  if (out) out.value = Math.round(state.t);
  render();
}

function update_elapsedTime(v) { playing = false; setPlayLabel(); state.t = v; render(); }
function toggle_massView(on) {
  state.mass = !!on;
  var cb = document.getElementById('massViewInput');
  if (cb) cb.checked = !!on;
  render();
}
function setPlayLabel() {
  var b = document.getElementById('playBtn');
  if (b) b.textContent = playing ? '❚❚ Pause' : '▶ Play diffusion';
}
function trigger_playDiffusion() {
  if (playing) { playing = false; setPlayLabel(); return; }
  if (state.t >= 100) setTime(0);
  playing = true; setPlayLabel();
}

function frame(ts) {
  var dt = lastTs ? Math.min(0.05, (ts - lastTs) / 1000) : 0;
  lastTs = ts;
  wob += dt * 1.6;
  if (playing) {
    var nt = state.t + dt * 15;
    if (nt >= 100) { nt = 100; playing = false; setPlayLabel(); }
    setTime(nt);
  } else {
    render();
  }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

/* ───────── demo step player ───────── */
var STEPS = [
  { title: 'Stopcock closed', n: 'Pure H₂ fills the left bulb and pure O₂ the right; the closed valve keeps them completely separated, so each gas sits at maximum concentration gradient across the neck.', t: 0, mass: false },
  { title: 'Stopcock just opened', n: 'Open the valve and the barrier vanishes. Molecules begin wandering across the neck; already a few white H₂ dots appear in the O₂ bulb while only one or two red O₂ dots have made it back.', t: 25, mass: false },
  { title: 'Why H₂ leads', n: 'Switch to the mass-coded view: at the same temperature the 2 g/mol H₂ molecules travel much faster than the 32 g/mol O₂ molecules, so the H₂ bulb drains into the O₂ side about four times more quickly.', t: 45, mass: true },
  { title: 'Some time after opening', n: 'Given enough time both gases are spread nearly uniformly across both bulbs. Molecules keep moving, but the net flux is zero because the concentration gradients have vanished.', t: 100, mass: true }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  var s = STEPS[stepIdx];
  playing = false; setPlayLabel();
  toggle_massView(s.mass);
  setTime(s.t);
  var nar = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (nar) nar.textContent = s.n;
  if (lab) lab.textContent = (stepIdx + 1) + ' / ' + STEPS.length + ' · ' + s.title;
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

